import { simulationVideo } from '@/data/media';
import type { MediaService } from '../types';
import { HERO_MODEL } from '@/lib/robot-nodes';
import { asset } from '@/lib/asset';

/** Generated by `npm run capture:stills` (own work). */
const STILLS = [1, 2, 3, 4, 5].map((i) => asset(`/img/stills/s${i}.webp`));
/**
 * Hand-kept manifest of assets present in public/. The hero model paths are always declared;
 * HeroRobot (M2) tries lo → hi and falls back to the §16 stand-in on load error, so dropping
 * amr_hero_lo.glb / amr_hero_hi.glb into public/models/ needs no code change.
 */
export const staticMedia: MediaService = { getVideo: (id) => (id === 'simulation' ? simulationVideo : null), hasDemoVideo: false, heroModel: { ...HERO_MODEL }, stillUrls: STILLS, posterUrl: asset('/img/hero-poster.webp'), mapStaticUrl: asset('/img/map-static.webp') };
